content.css:
/* ========================================================================== */
/* BFUSION Portfolio Health Matrix                                           */
/* ========================================================================== */
.bfusion-root {
  --phm-font-family: "Segoe UI";
  --phm-header-font: 11px;
  --phm-cell-font: 12px;
  --phm-legend-font: 11px;
  --phm-button-font: 11px;
  --phm-pct-label-font: 11px;
  --phm-title-font: 14px;
  --phm-subtitle-font: 11px;
  --phm-info-font: 11px;
  --phm-accent: #E8612A;
  width: 100%;
  height: 100%;
  overflow: auto;
  font-family: var(--phm-font-family), wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #FFFFFF;
  position: relative;
  padding-bottom: 24px;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
/* ========================================================================== */
/* Header (title + subtitle + info button)                                   */
/* ========================================================================== */
.phm-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-bottom: 1px solid #e5e7eb;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  position: relative;
}
.phm-header__titles {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.phm-header__title {
  font-size: var(--phm-title-font);
  font-weight: 600;
  color: #242424;
  line-height: 1.2;
}
.phm-header__subtitle {
  font-size: var(--phm-subtitle-font);
  color: #6C757D;
  line-height: 1.2;
}
.phm-header__info {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #d1d5db;
  background: #fff;
  color: #6b7280;
  font-style: italic;
  font-weight: 700;
  font-family: Georgia, serif;
  font-size: 12px;
  line-height: 1;
  cursor: pointer;
  padding: 0;
  flex-shrink: 0;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.phm-header__info:hover {
  background: var(--phm-accent);
  color: #fff;
  border-color: var(--phm-accent);
}
.phm-header__info-pop {
  position: absolute;
  top: calc(100% + 4px);
  right: 8px;
  width: 320px;
  max-width: 90%;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.12);
  padding: 12px 14px 14px 14px;
  z-index: 30;
  font-size: var(--phm-info-font);
  color: #242424;
  line-height: 1.4;
}
.phm-header__info-close {
  position: absolute;
  top: 4px;
  right: 6px;
  width: 20px;
  height: 20px;
  border: none;
  background: transparent;
  color: #6C757D;
  font-size: 16px;
  line-height: 1;
  cursor: pointer;
  padding: 0;
}
.phm-header__info-close:hover {
  color: #242424;
}
.phm-header__info-title {
  font-weight: 700;
  font-size: calc(var(--phm-info-font) + 1px);
  color: #1F2A44;
  padding-bottom: 4px;
  border-bottom: 2px solid var(--phm-accent);
  margin-bottom: 8px;
  padding-right: 18px;
}
.phm-header__info-desc {
  margin: 0 0 8px 0;
  color: #374151;
}
.phm-header__info-sub {
  font-weight: 600;
  color: #6C757D;
  margin-top: 6px;
  margin-bottom: 4px;
  font-size: calc(var(--phm-info-font) - 1px);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
.phm-header__info-bullets {
  margin: 0;
  padding-left: 18px;
}
.phm-header__info-bullets li {
  margin: 2px 0;
  color: #374151;
}
/* ========================================================================== */
/* Table Container                                                           */
/* ========================================================================== */
.bfusion-table-wrap {
  width: 100%;
  height: 100%;
  overflow: auto;
  display: block;
}
/* ========================================================================== */
/* Top Bar (Toolbar + Legend)                                                 */
/* ========================================================================== */
.phm-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 8px;
  border-bottom: 1px solid #e5e7eb;
  background: #fafafa;
  position: sticky;
  top: 0;
  z-index: 10;
  flex-wrap: wrap;
  gap: 6px;
}
.phm-toolbar {
  display: flex;
  gap: 6px;
}
.phm-btn {
  padding: 3px 10px;
  font-size: var(--phm-button-font);
  font-weight: 500;
  font-family: inherit;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  background: #fff;
  color: #374151;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.phm-btn:hover {
  background: #f3f4f6;
  border-color: #9ca3af;
}
.phm-btn:active {
  background: #e5e7eb;
}
/* ========================================================================== */
/* Legend                                                                     */
/* ========================================================================== */
.phm-legend {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-left: auto;
}
.phm-legend__item {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: var(--phm-legend-font);
  color: #6b7280;
  white-space: nowrap;
}
.phm-legend__dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 2px;
  flex-shrink: 0;
}
/* ========================================================================== */
/* Table                                                                     */
/* ========================================================================== */
.phm-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--phm-cell-font);
  table-layout: auto;
}
/* ========================================================================== */
/* Header Cells                                                              */
/* ========================================================================== */
.phm-th {
  padding: 6px 10px;
  font-size: var(--phm-header-font);
  font-weight: 600;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  text-align: left;
  white-space: nowrap;
  border-bottom: 2px solid #e5e7eb;
  background: #f9fafb;
  position: sticky;
  top: 33px;
  z-index: 5;
}
.phm-th--name {
  min-width: 180px;
}
.phm-th--health {
  text-align: center;
  min-width: 60px;
  width: 60px;
}
/* ========================================================================== */
/* Data Cells                                                                */
/* ========================================================================== */
.phm-td {
  padding: 5px 10px;
  border-bottom: 1px solid #f3f4f6;
  color: #374151;
  vertical-align: middle;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 200px;
}
.phm-td--name {
  font-weight: 500;
  color: #1f2937;
  max-width: 300px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.phm-td--group {
  font-weight: 700;
  color: #111827;
}
.phm-td--leaf {
  font-weight: 400;
  color: #374151;
}
.phm-td--num {
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: #374151;
}
.phm-td--health {
  text-align: center;
  width: 60px;
  min-width: 60px;
  padding: 4px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.4);
}
/* ========================================================================== */
/* Percent Done Bar                                                          */
/* ========================================================================== */
.phm-td--pct {
  padding: 5px 10px;
  border-bottom: 1px solid #f3f4f6;
  white-space: nowrap;
  min-width: 100px;
}
.phm-pctbar {
  display: inline-block;
  width: 60px;
  height: 8px;
  background: #e5e7eb;
  border-radius: 4px;
  overflow: hidden;
  vertical-align: middle;
}
.phm-pctbar__fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.2s ease;
}
.phm-pctbar__label {
  display: inline-block;
  margin-left: 6px;
  font-size: var(--phm-pct-label-font);
  font-weight: 500;
  color: #6b7280;
  vertical-align: middle;
}
/* ========================================================================== */
/* Toggle / Expand-Collapse                                                  */
/* ========================================================================== */
.phm-toggle {
  display: inline-block;
  width: 16px;
  font-size: 10px;
  cursor: pointer;
  color: #9ca3af;
  user-select: none;
  text-align: center;
  transition: color 0.15s;
}
.phm-toggle:hover {
  color: #374151;
}
.phm-toggle-spacer {
  display: inline-block;
  width: 16px;
}
/* ========================================================================== */
/* Rows                                                                      */
/* ========================================================================== */
.phm-row {
  cursor: pointer;
  transition: background 0.1s;
}
.phm-row:hover {
  background: #f0f4ff;
}
.phm-row--group {
  background: #f9fafb;
}
.phm-row--group:hover {
  background: #eef2ff;
}
.phm-row--leaf {
  background: #ffffff;
}
.phm-row--leaf:hover {
  background: #f0f4ff;
}
/* ========================================================================== */
/* Landing Page                                                              */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
/* ========================================================================== */
/* Empty Data State (cross-filter excluded everything)                        */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
